from reportlib import *
import numpy as np

def tab(path,label=None,cols=None):
 d=frame(path)
 if cols:d=d[[c for c in cols if c in d]]
 return (path,d,label or Path(path).stem.replace('_',' '))
def bootstrap(path):return tab(path,'Stored bootstrap contrasts; interpret named metric/difference exactly')
def run():
 base=dict(dataset='Local QASPER DEV 231 queries / 86 papers; train/internal validation where recorded',reader='Historical fine-tuned SARA / Mistral-7B',retriever='BM25 candidate pool; MiniLM semantic features/routing where specified',metric='Answer token F1; context-token accounting is artifact-specific')
 ctx=['configs/week4/week4_config.yaml']+[str(p) for p in Path('notebooks/week4').glob('*.ipynb')]
 paths=['results/week4/feature_discovery/feature_family_summary.csv','results/week4/feature_validation/feature_family_validation_summary.csv','results/week4/processed/model_comparison.csv','results/week4/model_benchmark/policy_comparison.csv','results/week4/qcca_v2/qcca_v2_policy_summary.csv','results/week4/qcca_v2_diagnostic/transition_model_comparison.csv','results/week4/qcca_v2_final_validation/policy_pareto_points.csv']
 qs=['Which pregeneration feature families associate with budget/transition targets?','Do associations survive redundancy and multiple-comparison checks?','Can direct budget prediction recover retrospective headroom?','Do transition classifiers improve the quality/cost decision?','Does sequential expansion avoid direct-classification collapse?','What do calibration and transition errors reveal about failures?','Does the selected C1 transition policy retain quality while reducing context?']
 names=['Feature discovery','Feature validation','Direct QCCA development','Transition model benchmark','Sequential QCCA-V2 modeling','QCCA-V2 diagnostic','QCCA-V2 final DEV validation']
 findings=['All feature-family maximum absolute Spearman correlations are below 0.19; observed individual associations are weak.','The six-family validation summary reports zero FDR-significant relationships at q0.10 in every family. Provisional feature retention is exploratory, not confirmed discovery.','QCCA-LogReg has F1 0.3034 and mean k2.03, below static k8 0.3950; high target-label agreement does not imply downstream quality.','Balanced logistic transition classification at threshold0.5 reaches recorded policy F1 0.3842; model-family/threshold tuning reuses DEV and is exploratory.','Unbalanced sequential logistic policy collapses to k2 (F1 0.3038). Balanced logistic reaches 0.3318; ridge reaches 0.3675, still below static k8.','Stored balanced/ridge policy F1 values are 0.3318/0.3675; transition quality and policy quality are distinct quantities.','Final C1 F1 is 0.3842 at 1115.9 tokens, versus k6 0.385699 at1359.1 and k8 0.394995 at1758.5; paired F1 intervals versus all three static references cross zero.']
 extras=[[],[tab('results/week4/feature_validation/provisional_feature_set.csv','Retained exploratory features',['feature','family','spearman_rho','q_value_fdr','bootstrap_ci_low','bootstrap_ci_high'])],[],[bootstrap('results/week4/model_benchmark/bootstrap_comparison.csv')],[bootstrap('results/week4/qcca_v2/bootstrap_policy_comparison.csv')],[],[bootstrap('results/week4/qcca_v2_final_validation/statistical_comparisons.csv')]]
 parts=[]
 for i,path in enumerate(paths):
  fig='results/week4/qcca_v2_diagnostic/figures/policy_pareto_frontier.png' if i==5 else None
  parts.append(part(['FEATURE-DISCOVERY','FEATURE-VALIDATION','QCCA-V1','MODEL-BENCHMARK','V2-MODELING','V2-DIAGNOSTIC','V2-FINAL'][i],names[i],qs[i],paths=[path],tables=[tab(path)]+extras[i],finding=findings[i],design=base,stats='Bootstrap/FDR results are reported only where a named CSV is included; nominal feature correlations are exploratory. See protocol source for grouping/resample definitions.',caveat='DEV reuse, many candidate comparisons and tied oracle labels limit generalization. Oracle points on a Pareto plot are retrospective ceilings, not deployable competitors. SOURCE CONFLICT: qcca_v2/bootstrap_policy_comparison.csv labels one 0.3038 quantity as difference versus k5; the true point difference from stored k5=0.3629 is about −0.0591. That row is not accepted as a valid contrast.' if i==4 else 'The same small DEV cohort supports feature discovery, policy selection and reported evaluation. No fresh confirmation exists in this week.',figures=[(fig,'X-axis is context tokens; y-axis answer F1. This is a DEV quality/cost plot; oracle curves must not be treated as achievable policy dominance.')] if fig else []))
 o=frame('results/week4/processed/oof_predictions.csv');recomp={c:float(o[c].mean()) for c in ['f1_pred_rule','f1_pred_logreg','f1_pred_tree']};assert len(o)==231
 write_week(4,'Test whether observable query/retrieval/content features can choose SARA representation budgets, then diagnose direct and sequential allocation failures.',parts,ctx,checks=['OOF file has 231 rows; recomputed means: '+str(recomp),'SOURCE CONFLICT: V2 bootstrap k5 contrast is mislabeled/numerically inconsistent; raw policy/static points retained.','Pareto flags mixing retrospective oracles and deployable policies are not interpreted as production dominance.'],negative='Several learned policies underperform static k8; no feature relationships survive family-reported q0.10 FDR; final F1 intervals cross zero.',decision='Final validation table identifies C1; no superiority claim follows. Later Week5 tests content representations and target formulations.',transition='Week5 content_allocator config introduces information ablations and frozen/adapted MiniLM encoders.',limits='OOF predictions do not erase exploratory feature/model/threshold selection on the same DEV cohort.');print('Legacy Week4',audit_legacy(4))
 p0='results/week5/tables/train_static_performance.csv';p1='results/week5/content_allocator/tables/main_results.csv';p2='results/week5/content_allocator/w5b/tables/w5b_main_results.csv';p3='results/week5/content_allocator/w5c_encoder_adaptation/tables/w5c_main_results.csv'
 parts=[part('TRAIN-SURFACE','Train response surface and supervision','Can allocation labels be generated from TRAIN responses rather than fitting only DEV?',paths=[p0,'results/week5/preflight/split_audit.json'],tables=[tab(p0),tab('results/week5/tables/dev_vs_train_target_distribution.csv')],design=base,finding='TRAIN fixed-k and supervision artifacts exist separately from DEV; the exact cohort/target distributions are retained in the tables.',caveat='Stored split audit is a historical metadata record, not proof of fresh holdout status after later exposure.'),part('A','Content-aware information / target ablation','Do passage semantics improve allocation over query-only/handcrafted inputs?',paths=[p1],tables=[tab(p1),bootstrap('results/week5/content_allocator/bootstrap/paper_clustered_bootstrap_results.csv')],design=base|{'encoder':'Frozen all-MiniLM-L6-v2; 2-layer Transformer allocator; seeds42/123/2026','targets':'T1 direct action classification / T2 regret regression'},finding='Most regret-model configurations return k8. I2-T2 reaches F1 0.3952 versus static0.3950 with only1.72% stored token reduction; this is not a strong adaptive breakthrough.',caveat='SOURCE CONFLICT: Week5 uses hard-coded k8 cost1750.5 versus Week2 raw1758.5; fixed-k costs differ by8 tokens. src/week5/evaluation.py and supervision.py encode inconsistent reference constants. Preserve both definitions, never pool the reduction percentages.'),part('B','Multilabel admissibility formulation','Can predicting an admissible action set avoid direct-label ambiguity and fallback collapse?',paths=[p2],tables=[tab(p2),tab('results/week5/content_allocator/w5b/tables/w5b_seed_results.csv'),bootstrap('results/week5/content_allocator/w5b/bootstrap/w5b_bootstrap_comparisons.csv')],design=base|{'target':'T3 multilabel action admissibility; selected tau'},finding='Completed seed-level and aggregate T3 outputs exist. The table reports fallback rates alongside F1; oracle quality/cost entries are retrospective references.',caveat='SOURCE CONFLICT: Quality Oracle token cost is846.1 in A versus1021.5 in B/C despite the same printed oracle F1/k. Cost identity is not established as equivalent; do not infer compression improvements from the mismatch.'),part('C','Encoder adaptation','Does unfreezing MiniLM layers improve content-aware allocation?',paths=[p3],tables=[tab(p3),bootstrap('results/week5/content_allocator/w5c_encoder_adaptation/bootstrap/w5c_bootstrap_comparisons.csv')],design=base|{'encoders':'C0 frozen; C1 last layer trainable; C2 last2 layers trainable'},finding='C0 mean F1 0.381033 exceeds last1-layer0.3620 and last2-layer0.3743 point estimates. Encoder adaptation does not show a robust improvement over frozen features or static k8.',caveat='Seed SD is not a paper-cluster CI. Internal-VAL threshold selection and DEV evaluation must remain distinct.')]
 contexts=[str(p) for p in Path('configs/week5').glob('*.yaml')]+[str(p) for p in Path('notebooks/week5').glob('*.ipynb')]+['src/week5/evaluation.py','src/week5/supervision.py']
 write_week(5,'Use TRAIN response supervision and content-aware encoders to learn cost-aware SARA budget allocation.',parts,contexts,checks=['Source-level token reference conflict documented: 1750.5 vs1758.5.','Oracle cost conflict across A/B/C retained instead of silently choosing a number.'],negative='Fallback-to-k8, weak content gains and worse adapted-encoder point estimates remain visible.',decision='No universal content-aware allocator superiority established; frozen semantic information motivates passage-routing tests.',transition='Week6 asks WHICH passages should be kept at a fixed k, rather than predicting k alone.',limits='Historical DEV reuse, seed variability, target definitions and inconsistent token-accounting constants.');print('Legacy Week5',audit_legacy(5))
 p0='results/week6/passage_routing/tables/w6_main_results.csv';p1='results/week6/hybrid_routing/tables/w6b_main_results.csv'
 parts=[part('A','Fixed-budget passage-fidelity routing','Does choosing WHICH retrieved passages remain verbatim improve SARA at the same k?',paths=[p0],tables=[tab(p0),tab('results/week6/passage_routing/tables/w6_routing_quality.csv'),bootstrap('results/week6/passage_routing/bootstrap/w6_bootstrap_comparisons.csv')],design=base|{'k':[2,4,6],'methods':'BM25 prefix; MiniLM semantic top-k; learned router'},finding='At k4, semantic routing reaches0.391333 versus BM25-prefix0.359601 and learned routing0.357210. At k6, semantic0.395345 versus BM250.385699. This tests routing inside a fixed retrieved pool.',caveat='MiniLM is the semantic routing encoder here, not SFR. Baseline latency entries are0 for cached references; they are not physical zero-latency systems.'),part('B','Hybrid semantic / lexical routing','Does score fusion improve on pure semantic routing?',paths=[p1],tables=[tab(p1),bootstrap('results/week6/hybrid_routing/bootstrap/w6b_bootstrap_comparisons.csv')],design=base|{'methods':'R3 fixed fusion and R4 reciprocal-rank fusion'},finding='RRF is best at k2 by point estimate0.325764, but semantic routing remains stronger at k4/k6 than fixed fusion or RRF. No universal hybrid routing gain is established.',caveat='Method selection/alpha tuning use internal validation. Output generation timing omits cached baseline work and must not be read as end-to-end throughput.')]
 # One independent generation-file coverage check without re-running a model.
 gp='results/week6/passage_routing/sara_generations/dev_sara_generations.jsonl';gg=pd.read_json(ROOT/gp,lines=True);print('W6 raw schema',len(gg),list(gg.columns))
 write_week(6,'Separate passage identity from representation budget: fix k and compare routing strategies within the same candidate pool.',parts,[str(p) for p in Path('configs/week6').glob('*.yaml')]+[str(p) for p in Path('notebooks/week6').glob('*.ipynb')],checks=[f'Saved DEV generation JSONL coverage: {len(gg)} records; columns: '+','.join(gg.columns)],extra_sources=[gp],negative='Learned routing underperforms simple semantic routing; fusion is not consistently best.',decision='Carry simple semantic routing into budget/routing composition experiments.',transition='Week7 composes prior budget prediction with semantic routing and explores retraining/anchors/multiple fidelities.',limits='Same local DEV, semantic encoder limitations and cached/uncached latency asymmetry.');print('Legacy Week6',audit_legacy(6))
 specs=[('A','Budget × routing composition','Can the old W4 allocator benefit from semantic routing?','w7a_budget_semantic_composition','w7a_main_results.csv','Old allocator + semantic routing F1 is0.378150, below the same allocator with BM250.384172 and static semantic k40.391333.'),('B','Semantic-budget relearning','Can retraining on a semantic response surface improve allocation?','w7b_semantic_budget','w7b_main_dev_results.csv','New semantic-aware allocator F1 is0.3522 versus semantic k40.3909 and k80.4010; its retrospective epsilon oracle0.4869 is not deployable.'),('C','Retrieval-aware sufficiency','Do richer routing-aware features identify the smallest sufficient budget?','w7c_retrieval_aware_allocator','w7c_main_dev_results.csv','Selected sufficiency allocator F1 is0.378323 at mean k6.8485, below static semantic k40.390929.'),('C2','Utility-aware ranking','Does direct utility regression/ranking improve the quality/cost tradeoff?','w7c2_utility_ranking','w7c2_main_dev_results.csv','Selected utility-ranking model F1 is0.392233 at mean k7.3853 and1622.10 tokens, below static k80.401041.'),('C3','Anchor and deviate','Can safe down/up shifts around semantic k4 improve the anchor?','w7c3_anchor_deviate','w7c3_main_dev_results.csv','Anchor-and-deviate F1 is0.380107 at903.10 tokens versus anchor k40.390929 at921.06 tokens; limited savings come with lower point quality.'),('D','Cross-encoder fidelity router','Do stronger learned representations make safer allocation changes?','w7d_cross_encoder_router','w7d_main_dev_results.csv','Hierarchical frozen/unfrozen DEV policies collapse to static k4 (F10.390929); listwise7B LoRA reaches0.387714. Internal-VAL table values are different cohorts, not competing DEV scores.'),('E','Multifidelity evidence representation','Does adding medium extractive evidence recover k6 quality cheaply?','w7e_multifidelity','w7e_main_dev_results.csv','Repaired hybrid E1-H F10.3861 exceeds corrected extract-only0.3755, but trails static k40.3909 while using more tokens. Medium representation does not establish net quality/cost benefit.')]
 parts=[]
 for id,name,rq,sub,file,finding in specs:
  path=f'results/week7/{sub}/tables/{file}';bs=list(Path(f'results/week7/{sub}/bootstrap').glob('*.csv'));ts=[tab(path)]+[bootstrap(str(x)) for x in bs];figs=[]
  ff=next(iter(Path(f'results/week7/{sub}/figures').glob('*quality*token*.png')),None)
  if ff:figs=[(str(ff),'Horizontal axis is context/token cost; vertical axis is answer F1. It visualizes the recorded DEV frontier; retrospective oracle points are not deployable comparisons.')]
  parts.append(part(id,name,rq,paths=[path],tables=ts,design=base|{'routing':'MiniLM semantic top-k within BM25 top10; k2/4/5/6/8 where evaluated'},finding=finding,stats='Stored per-part bootstrap CSVs are included where present. Check whether the CI is a paired difference; seed/cluster details come from the corresponding config. No new multiplicity-corrected family is invented.',caveat='SOURCE CONFLICT: W7A imported semantic k4 F1=0.391333 differs from later semantic-surface k4=0.390929; small but beyond six-decimal rounding. Keep part-specific generation/table identities. Oracle F1 also appears rounded/copied across parts; do not treat repeated oracle references as independent experiments.',figures=figs))
 write_week(7,'Test whether semantic routing plus adaptive budget decisions or medium-fidelity representations can improve static semantic context policies.',parts,[str(p) for p in Path('configs/week7').glob('*.yaml')]+[str(p) for p in Path('notebooks/week7').glob('*.ipynb')],checks=['Part-specific static/reference drift is documented, not silently normalized.','Internal-VAL and DEV result tables retain their cohort labels.'],negative='Retrained, sufficiency, utility and anchor policies generally fail to improve static quality; multifidelity medium extraction adds cost without clear net gain.',decision='Simple fixed semantic budgets remain strong references; learned global-k and medium-fidelity choices are not universally promoted.',transition='Week8 notebooks add draft-conditioned diagnostics, promotion outcomes, utility models and full-system controls.',limits='Repeated exploratory DEV exposure, outcome-derived oracle targets, semantic-encoder limitations, baseline drift and separate train/VAL/DEV scopes.');print('Legacy Week7',audit_legacy(7))
if __name__=='__main__':run()
